public static String base64Decode(final String s) {
    // Initialize the output with an empty string
    String output = "";

    // If the input is null or empty, return an empty string
    if (s == null || s.isEmpty()) {
        return output;
    }

    // Pad the input with trailing '=' if necessary
    s = s.replaceAll("\\s", "");
    while (s.length() % 4 != 0) {
        s += "=";
    }

    // Convert each four-byte group into a three-byte group
    for (int i = 0; i < s.length(); i += 4) {
        // Check if all four characters are in the Base64 alphabet
        if (!(s.charAt(i) >= 'A' && s.charAt(i) <= 'Z' ||
                s.charAt(i) >= 'a' && s.charAt(i) <= 'z' ||
                s.charAt(i) >= '0' && s.charAt(i) <= '9' ||
                s.charAt(i) == '+' || s.charAt(i) == '=')) {
            throw new IllegalArgumentException("Illegal character in Base64 string");
        }

        // Convert the first three characters to an integer
        int val = 0;
        for (int j = 2; j >= 0; j--) {
            val = (val << 6) + s.charAt(i + j);
        }

        // Convert the integer to a three-byte group
        String group = "";
        for (int j = 0; j < 3; j++) {
            group = (char) (val >> (j * 8) & 0xFF) + group;
        }

        // Append the three-byte group to the output
        output += group;
    }

    // Return the decoded string
    return output;
}

