public void enlarge(final int size) {
  // Step 1: Check if the current capacity is enough to accommodate the additional bytes
  if (size <= 0) {
    return;
  }

  // Step 2: Calculate the new capacity that we need to accommodate the additional bytes
  int newCapacity = (int) Math.ceil(this.elements.length * 1.5);
  if (newCapacity < this.elements.length + size) {
    newCapacity = this.elements.length + size;
  }

  // Step 3: Create a new array with the new capacity
  byte[] newElements = new byte[newCapacity];

  // Step 4: Copy the elements from the old array to the new array
  System.arraycopy(this.elements, 0, newElements, 0, this.size);

  // Step 5: Set the new elements as the current elements
  this.elements = newElements;
}

