public long readLong(final int offset) {
    // Step 1: Check the validity of the input
    if (offset < 0 || offset > this.content.length - 8) {
        throw new IndexOutOfBoundsException("Offset is out of bounds: " + offset);
    }

    // Step 2: Read the bytes of the long value
    byte[] bytes = new byte[8];
    for (int i = 0; i < 8; i++) {
        bytes[i] = this.content[offset + i];
    }

    // Step 3: Convert the bytes to a long value
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value |= ((long) bytes[i] & 0xFF) << (8 * i);
    }

    // Step 4: Return the long value
    return value;
}

