public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Step 1: Validate the input parameters
    if (byteArrayValue == null && byteOffset < 0 && byteLength <= 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Step 2: Enlarge the byte vector if necessary
    if (this.data.length - this.length < byteLength) {
        this.data = Arrays.copyOf(this.data, this.data.length + Math.max(byteLength, this.data.length));
    }

    // Step 3: Copy the bytes from byteArrayValue to this ByteVector
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    this.length += byteLength;

    return this;
