private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getLeftChild() == null) {
        throw new IllegalArgumentException("Cannot perform right rotation on a node with no left child");
    }

    // Get the left child of the current node
    TreeNode<T> leftChild = node.getLeftChild();

    // Make the current node the right child of its left child
    leftChild.setRightChild(node);

    // Update the parent of the current node
    if (node.getParent() != null) {
        node.getParent().setLeftChild(leftChild);
    }

    // Set the parent of the left child to the current node
    leftChild.setParent(node);

    // Update the parent of the left child
    leftChild.setParent(null);

    // Return the new parent of the node
    return leftChild;
}

