  if (arr == null) {
    throw new IllegalArgumentException("The array cannot be null");
  }
  if (from < 0 || from >= arr.length || to < 0 || to >= arr.length) {
    throw new IllegalArgumentException("The indices must be within the bounds of the array");
  }
  if (from > to) {
    throw new IllegalArgumentException("The from index must be less than or equal to the to index");
  }

  int length = to - from + 1;
  if (length <= 1) {
    return;
