private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize a circulator to the starting node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Loop until we find a node that satisfies the predicate or reach the end of the component
    while (circulator.hasNext() && !predicate.test(circulator.next())) {
        // If we reach the end of the component, reset the circulator to the starting node
        if (circulator.next().equals(stop)) {
            circulator = new OuterFaceCirculator(start, dir);
        }
    }

    // Return the circulator to the node that satisfies the predicate or the stop node
    return circulator;
}

