private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // 1. Check input bounds is non-empty
    // 2. Input length is less than 2.
    if(bounds.size() == 0 || bounds.size() == 1){
      return Pair.of(new ArrayList<Integer>(), 0L);
    }

    // 3. Sort the list
    Collections.sort(bounds);

    // 4. Compute the suffix sum
    List<Integer> suffixSums = new ArrayList<>();
    for(int i = bounds.size() - 1; i >= 0; i--){
        suffixSums.add(bounds.get(i));
    }

    // 5. Get the sum of all elements
    long sum = 0;
    for(Integer bound : bounds){
        sum += bound;
    }

    // 6. Return the pair
    return Pair.of(suffixSums, sum);
}

