    if (input.startsWith("\"")) {
        // If the input starts with a quote, remove the first character
        input = input.substring(1);
    }

    // Step 3: Check if the input ends with a quote
    if (input.endsWith("\"")) {
        // If the input ends with a quote, remove the last character
        input = input.substring(0, input.length() - 1);
    }

    // Step 4: Check if the input contains any escaped characters
    if (input.contains("\\")) {
        // If the input contains escaped characters, replace them with the corresponding literal characters
        input = input.replace("\\',", "'");
        input = input.replace("\\\",", "\"");
    }

    return input;
}

