private void check(String modelName) throws IllegalStateException {
  // check for continuous sharding key indices
  List<Integer> shardingKeyIndices = getShardingKeyIndices(modelName);
  if (shardingKeyIndices.size() == 0) {
    return;
  }

  int previousKey = shardingKeyIndices.get(0);
  for (int i = 1; i < shardingKeyIndices.size(); i++) {
    int currentKey = shardingKeyIndices.get(i);
    if (currentKey - previousKey != 1) {
      throw new IllegalStateException("Sharding key indices are not continuous.");
    }
    previousKey = currentKey;
  }
}

