static long compressTimeBucket(long timeBucket, int dayStep) {
    // Handle edge cases
    if (dayStep < 1) {
        throw new IllegalArgumentException("Day step must be greater than 0");
    }
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket must be a positive number");
    }

    // Determine the offset
    int offset = dayStep - 1;

    // Calculate the number of days in the time bucket
    long days = timeBucket / 100;

    // Calculate the date of the first day in the time bucket
    long date = days * 100 + offset + 1;

    // Determine the day of the week of the first day in the time bucket
    int dayOfWeek = getDayOfWeek(date);

    // Determine the number of days to add to the date to get to the end of the time bucket
    int numDaysToAdd = (dayStep - dayOfWeek + 7) % 7;

    // Calculate the new date
    long newDate = date + numDaysToAdd;

    // Calculate the new time bucket
    long newTimeBucket = newDate * 100;

    return newTimeBucket;
}

