    // Step 1: Check if the buffer is empty
    if (this.isEmpty()) {
        return new byte[0];
    }

    // Step 2: Allocate a byte array of the required size
    int totalSize = 0;
    for (int i = 0; i < this.buffers.length; i++) {
        totalSize += this.buffers[i].remaining();
    }
    byte[] result = new byte[totalSize];

    // Step 3: Copy the contents of each buffer into the result array
    int offset = 0;
    for (int i = 0; i < this.buffers.length; i++) {
        int len = this.buffers[i].remaining();
        this.buffers[i].get(result, offset, len);
        offset += len;
    }

    // Step 4: Return the result array
    return result;
}

